"""Что доступно на этой машине: модели и языки."""
import os

# Новая схема скачивания HuggingFace (Xet) качает в своих потоках, и наша
# отмена до них не доходит: закачка идёт дальше, как будто её не просили
# встать. Старый путь встаёт честно. Библиотека читает переменную один раз,
# при импорте, — поэтому ставим её здесь, раньше всех, кто её импортирует:
# и загрузчик моделей, и faster-whisper подтягивают huggingface_hub у себя.
os.environ.setdefault("HF_HUB_DISABLE_XET", "1")
